<template>
  <div class="full-width">
    <div
      v-if="formBuilderConfigModel[fieldName].displayLabelOnLeft"
      :style="'width:' + formBuilderConfigModel[fieldName].labelWidth + '%'"
      class="display-block"
    >
      <div :class="fieldName + '  full-width'">
        {{
          getFieldLabel(
            formBuilderConfigModel[fieldName],
            '',
          )
        }}

        <span v-if="false" class="text-red"> * </span>
      </div>
    </div>

    <div
      :style="
        'width:' + getInputFieldWidth(formBuilderConfigModel[fieldName]) + '%'
      "
      class="display-block"
    >
      <div
        class="col-sm-12 col-md-12 col-lg-12 display-flex"
        v-if="!formBuilderConfigModel[fieldName].displayLabelOnLeft"
      >
        <div class="ellipsify" :class="fieldName + ' full-width'">
          {{
            getFieldLabel(
              formBuilderConfigModel[fieldName],
              '',
            )
          }}

          <span v-if="false" class="text-red"> * </span>

          <q-tooltip>{{
            getFieldLabel(
              formBuilderConfigModel[fieldName],
              '',
            )
          }}</q-tooltip>
        </div>
      </div>

      <div
        :id="fieldName"
        child_type="textarea"
        class="col-sm-12 col-md-12 col-lg-12"
      >
        <q-input
          outlined
          dense
          autogrow
          :data-name="fieldName"
          :disable="isReadOnly"
          v-model="notes"
          :tabindex="formBuilderConfigModel[fieldName].tabIndex"
          :class="
            ' full-width ' +
            (fieldName + '_input ') +
            formBuilderConfigModel[fieldName].color +
            ' ' +
            formBuilderModel[fieldName].name
          "
          @update:model-value="
            (val: any) => {
              modelUpdated(val);
            }
          "
        >
          <template v-slot:append>
            <q-badge
              v-if="isFormBuilderMode && showTabIndex"
              color="orange"
              text-color="black"
              :label="formBuilderConfigModel[fieldName].tabIndex"
            />
          </template>
        </q-input>
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import displayFieldLabel from 'src/utils/displayFieldLabel';
import { useFormBuilderStore, useDocumentStore } from 'src/store/main';
import formBuilderHelper from 'src/formBuilder/utils/formBuilderHelper';
import { notify } from 'src/components/notifications/notify';

export default defineComponent({
  name: 'TextInput',
  components: {},
  props: {
    currentField: {
      type: Object,
      default: new Object(),
    },
    fieldName: {
      type: String,
      default: '',
    },
    isReadOnly: {
      type: Boolean,
      default: false,
    },
    groupIndex: {
      type: Number,
      default: 0,
    },
  },
  emits: ['inputClicked', 'inputValueChanges', 'updateModel'],
  mixins: [displayFieldLabel, formBuilderHelper],

  beforeMount: function () {
    if (this.isFormBuilderMode) {
      this.$emit('updateModel', this.currentField);
    }
  },
  mounted: function () {
    this.init();
  },
  // unmounted: function () {
  // },

  methods: {
    init() {
      if (this.record.notes) {
        this.notes = this.record.notes;
      }
    },
    // Need to add delay as formBuilderModel did not updated as soon as user manually typed in the field
    modelUpdated(val: any) {
      if (this.isFormBuilderMode) {
        return;
      }
      this.record.notes = val;
    },
  },
  setup() {
    const form_builder_store = useFormBuilderStore();
    const {
      formBuilderModel,
      isFormBuilderMode,
      formBuilderConfigModel,
      formLayout,
      showTabIndex,
    } = storeToRefs(form_builder_store);

    const doc_store = useDocumentStore();
    const { record } = storeToRefs(doc_store);

    return {
      record,
      formLayout,
      showTabIndex,
      formBuilderModel,
      isFormBuilderMode,
      formBuilderConfigModel,
      notes: ref(''),
    };
  },
});
</script>
